function exportReport(b:StrengthBundle,filter:string,pending:AspectId[]){const rows:unknown[][]=[['SK@S — LAPORAN KEKUATAN KAMI'],['Sekolah',b.school.name],['Kod sekolah',b.school.code],['Tahun',b.year],['Aspek','Nama','Status','Pengisi','Penyemak','Disahkan pada','Maklumat','Nilai','Unit / catatan']];for(const r of b.records.filter(r=>r.canRead&&(filter!=='verified'||r.status==='verified'&&!pending.includes(r.aspect)))){const prefix=[r.aspect,ASPECTS.find(a=>a.id===r.aspect)!.name,pending.includes(r.aspect)?'Draf pada peranti':STATUS_NAMES[r.status],person(b,r.assigneeId),person(b,r.reviewerId),date(r.verifiedAt)];for(const m of strengthMetrics(r.aspect,r.data))rows.push([...prefix,m.label,m.value??'',m.unit+(m.note?' · '+m.note:'')]);if(r.data.applicable)for(const f of FIELDS[r.aspect]??[])rows.push([...prefix,f.label,r.data.values[f.key]??'',f.percent?'%':'orang']);if(r.data.applicable)for(const item of r.data.rows){rows.push([...prefix,item.name+' — sedia ada',item.existing??'','unit']);rows.push([...prefix,item.name+' — berfungsi',item.working??'','unit']);}for(const p of r.aspect==='A9'?r.data.programs:[]){rows.push([...prefix,p.name+' — dilaksanakan',p.held?'Ya':'Tidak','']);if(p.held){rows.push([...prefix,p.name+' — kehadiran',p.attendance??'','orang']);rows.push([...prefix,p.name+' — ibu bapa / penjaga',p.parents??'','orang']);}}rows.push([...prefix,'Catatan',r.data.notes,'']);for(const url of r.data.evidence)rows.push([...prefix,'Evidens',url,'']);}downloadCSV(rows,`SKAS_Kekuatan_Kami_${b.school.code}_${b.year}.csv`);}
function StrengthReport({bundle:b,filter,pending}:{bundle:StrengthBundle;filter:string;pending:AspectId[]}){const visible=b.records.filter(r=>r.canRead&&(filter!=='verified'||r.status==='verified'&&!pending.includes(r.aspect)));return <section className="skas-report"><header><div><span className="skas-kicker">SK@S · KEKUATAN KAMI</span><h2>Laporan tahun {b.year}</h2><p>{b.school.name} · {b.school.code}</p></div><p>Dicetak: {date(new Date().toISOString())}<br/>{filter==='verified'?'Rekod disahkan sahaja':'Semua status yang dibenarkan'}</p></header><p className="skas-report-note">Status pengesahan adalah bagi setiap aspek. Draf dan rekod pada peranti belum dianggap disahkan. Angka ini tidak digabungkan menjadi skor keseluruhan sekolah.</p>{!visible.length&&<p>Tiada rekod sepadan dengan akses dan penapis yang dipilih.</p>}{visible.map(r=><article className="skas-report-aspect" key={r.aspect}><div className="skas-section-heading"><h3>{r.aspect} · {ASPECTS.find(a=>a.id===r.aspect)!.name}</h3>{status(r,pending.includes(r.aspect))}</div><p>Pengisi: {person(b,r.assigneeId)}<br/>Penyemak: {person(b,r.reviewerId)}<br/>Disahkan oleh: {r.verifiedBy?person(b,r.verifiedBy):'Belum disahkan'} · {date(r.verifiedAt)}</p>{(r.aspect==='A2'||r.aspect==='A7')&&<p><b>Tahun rujukan {r.year-1}</b> bagi {r.aspect==='A2'?'rumusan Standard 4':'pengguna aktif DELIMa'}.</p>}<table><thead><tr><th>INDIKATOR</th><th>NILAI</th></tr></thead><tbody>{strengthMetrics(r.aspect,r.data).map((m,i)=><tr key={i}><td>{m.label}{m.note&&<small>{m.note}</small>}</td><td>{valueText(m.value,m.unit)}</td></tr>)}</tbody></table>{r.data.applicable&&<><table><tbody>{(FIELDS[r.aspect]??[]).map(f=><tr key={f.key}><td>{f.label}</td><td>{valueText(r.data.values[f.key],f.percent?'%':'orang')}</td></tr>)}</tbody></table>{r.data.rows.length>0&&<table><thead><tr><th>PRASARANA / PERANTI</th><th>SEDIA ADA</th><th>BERFUNGSI</th></tr></thead><tbody>{r.data.rows.map(row=><tr key={row.id}><td>{row.name||'Belum dipilih'}</td><td>{valueText(row.existing)}</td><td>{valueText(row.working)}</td></tr>)}</tbody></table>}{r.aspect==='A9'&&<table><thead><tr><th>PROGRAM</th><th>KEHADIRAN</th><th>IBU BAPA / PENJAGA</th></tr></thead><tbody>{r.data.programs.map(p=><tr key={p.id}><td>{p.name} {!p.held&&<small>Tidak dilaksanakan</small>}</td><td>{p.held?valueText(p.attendance):'—'}</td><td>{p.held?valueText(p.parents):'—'}</td></tr>)}</tbody></table>}</>}<div className="skas-report-notes"><b>Catatan / sumber</b><p>{r.data.notes||'Tiada catatan.'}</p>{r.data.evidence.length>0&&<><b>Pautan evidens</b><ol>{r.data.evidence.map(url=><li key={url}><a href={url} target="_blank" rel="noopener noreferrer">{url}</a></li>)}</ol></>}</div></article>)}</section>;}
